from copy import deepcopy

from project_orchestrator.canon_ledger_summary import summarize_ledger


def test_supervisor_acceptance_empty():
    assert summarize_ledger({}) == {
        'packet_count': 0, 'state_counts': {}, 'accepted_refs': [], 'last_event_type': None,
    }


def test_supervisor_acceptance_counts_refs_and_last_event():
    ledger = {
        'packets': {
            'p3': {'state': 'BLOCKED'},
            'p1': {'state': 'ACCEPTED_LOCAL', 'accepted_ref': 'refs/iron-god/accepted/p1'},
            'p2': {'state': 'ACCEPTED_LOCAL', 'accepted_ref': 'refs/iron-god/accepted/b'},
            'p4': {'state': 'DISPATCHED', 'accepted_ref': ''},
        },
        'events': [{'type': 'DISPATCHED'}, {'type': 'LOCAL_ACCEPTANCE'}],
    }
    before = deepcopy(ledger)
    summary = summarize_ledger(ledger)
    assert ledger == before
    assert summary['packet_count'] == 4
    assert summary['state_counts'] == {'ACCEPTED_LOCAL': 2, 'BLOCKED': 1, 'DISPATCHED': 1}
    assert list(summary['state_counts']) == sorted(summary['state_counts'])
    assert summary['accepted_refs'] == ['refs/iron-god/accepted/b', 'refs/iron-god/accepted/p1']
    assert summary['last_event_type'] == 'LOCAL_ACCEPTANCE'

