from copy import deepcopy

from project_orchestrator.canon_ledger_attention import packets_needing_attention


def test_supervisor_acceptance_empty():
    assert packets_needing_attention({}) == {'active': [], 'waiting_for_supervisor': [], 'retry_exhausted': []}


def test_supervisor_acceptance_classifies_packets():
    ledger = {'packets': {
        'b': {'state': 'IMPLEMENTING'}, 'a': {'state': 'DISPATCHED'},
        'w': {'state': 'WAITING_FOR_SUPERVISOR'},
        'x': {'state': 'PARKED', 'attempt_count': 3}, 'y': {'state': 'BLOCKED', 'attempt_count': 2},
        'z': {'state': 'BLOCKED'}, 'v': {'state': 'BLOCKED', 'attempt_count': 4}, 'ok': {'state': 'ACCEPTED_LOCAL'},
    }}
    before = deepcopy(ledger)
    assert packets_needing_attention(ledger) == {
        'active': ['a', 'b'], 'waiting_for_supervisor': ['w'], 'retry_exhausted': ['v', 'x'],
    }
    assert ledger == before
    assert packets_needing_attention(ledger, max_attempts=2)['retry_exhausted'] == ['v', 'x', 'y']

from copy import deepcopy

from project_orchestrator.capability_profile_report import summarize_capability_profile


def test_supervisor_acceptance_empty():
    assert summarize_capability_profile({}) == {'model': None, 'max_passing_level': 0, 'levels': []}


def test_supervisor_acceptance_sorts_levels_numerically():
    profile = {'model': 'ollama/qwen2.5-coder:7b', 'max_passing_level': 2, 'extra': True, 'levels': {
        '10': {'pass_rate': 0.0, 'status': 'SKIPPED_LOWER_LEVEL_FAILED'},
        '2': {'pass_rate': 1.0, 'median_wall_s': 48.2, 'status': 'MEASURED', 'runs': []},
        '1': {'pass_rate': 1.0, 'median_wall_s': 32.1, 'status': 'MEASURED'},
    }}
    before = deepcopy(profile)
    assert summarize_capability_profile(profile) == {
        'model': 'ollama/qwen2.5-coder:7b', 'max_passing_level': 2, 'levels': [
            {'level': 1, 'pass_rate': 1.0, 'median_wall_s': 32.1, 'status': 'MEASURED'},
            {'level': 2, 'pass_rate': 1.0, 'median_wall_s': 48.2, 'status': 'MEASURED'},
            {'level': 10, 'pass_rate': 0.0, 'median_wall_s': None, 'status': 'SKIPPED_LOWER_LEVEL_FAILED'},
        ]}
    assert profile == before
